let S=initState();S.reveal={a1:['CV1']};
let V={role:'atleta',aid:'a1',cid:'tr1',tab:{atleta:'inicio',resp:'inicio',trn:'turma',saci:'painel'},page:'comp',modal:null,toast:null,form:{}};
const esc=s=>String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const A=id=>S.athletes.find(a=>a.id===id),P=id=>S.partners.find(p=>p.id===id),T=id=>S.coaches.find(c=>c.id===id);
const fd=d=>{if(!d)return'';const x=d.split('-');return x[2]+'/'+x[1]+'/'+x[0]};
const dd=d=>d.split('-')[2],mm=d=>['jan','fev','mar','abr','mai','jun','jul','ago','set','out','nov','dez'][+d.split('-')[1]-1];
const brl=v=>v?'R$ '+v.toFixed(2).replace('.',','):'Gratuito';
const isPlay=a=>a.cat==='Sub-9'||a.cat==='Sub-11';
const uid=()=>'x'+Math.random().toString(36).slice(2,8);
const IC={home:'<path d="M3 11l9-8 9 8M5 10v10h5v-6h4v6h5V10"/>',album:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h4"/>',trail:'<circle cx="6" cy="19" r="2"/><circle cx="18" cy="5" r="2"/><path d="M8 19h6a4 4 0 000-8h-4a4 4 0 010-8h6"/>',book:'<path d="M4 5a2 2 0 012-2h13v16H6a2 2 0 00-2 2zM4 19a2 2 0 002 2h13"/>',cal:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4"/>',shield:'<path d="M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z"/><path d="M9 12l2 2 4-4"/>',trophy:'<path d="M7 4h10v5a5 5 0 01-10 0zM7 6H4v2a3 3 0 003 3M17 6h3v2a3 3 0 01-3 3M12 14v4M8 21h8"/>',ball:'<circle cx="12" cy="12" r="9"/><path d="M12 8l3 2-1 4h-4l-1-4zM12 3v5M21 10l-6 0M4 9l5 1M8 20l2-6M16 20l-2-6"/>',star:'<path d="M12 3l2.8 5.7 6.2.9-4.5 4.4 1 6.2L12 17.2 6.5 20.2l1-6.2L3 9.6l6.2-.9z"/>',flag:'<path d="M5 21V4M5 4h12l-2 4 2 4H5"/>',check:'<path d="M5 12l5 5 9-10"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',lock:'<rect x="5" y="11" width="14" height="10" rx="2"/><path d="M8 11V8a4 4 0 018 0v3"/>',play:'<path d="M8 5v14l11-7z"/>',bell:'<path d="M6 17V11a6 6 0 0112 0v6l2 2H4zM10 21h4"/>'};
const ic=(n,s)=>`<svg width="${s||20}" height="${s||20}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${IC[n]||''}</svg>`;
function avatar(a,s){const v=a.avatar,sk=SKINS[v.skin],hc=HAIRC[v.hc],hs=HAIRS[v.hair];
 const hair=hs==='cacheado'?`<circle cx="30" cy="22" r="5" fill="${hc}"/><circle cx="50" cy="22" r="5" fill="${hc}"/><circle cx="40" cy="17" r="6" fill="${hc}"/><circle cx="24" cy="29" r="4" fill="${hc}"/><circle cx="56" cy="29" r="4" fill="${hc}"/>`:hs==='curto'?`<path d="M24 30c0-12 7-17 16-17s16 5 16 17c-4-5-9-7-16-7s-12 2-16 7z" fill="${hc}"/>`:`<path d="M26 27c2-9 8-12 14-12s12 3 14 12c-5-3-9-4-14-4s-9 1-14 4z" fill="${hc}" opacity=".6"/>`;
 return `<svg class="av" width="${s}" height="${s}" viewBox="0 0 80 80"><circle cx="40" cy="40" r="40" fill="#f3d9d9"/><path d="M14 80c0-14 11-22 26-22s26 8 26 22z" fill="#C4161C"/><path d="M33 58l7 7 7-7" stroke="#fff" stroke-width="3" fill="none"/><text x="40" y="77" font-size="9" font-weight="800" fill="#fff" text-anchor="middle" font-family="system-ui">${a.id==="a1"?10:a.id==="a2"?7:9}</text><rect x="34" y="46" width="12" height="12" rx="4" fill="${sk}"/><circle cx="40" cy="34" r="15" fill="${sk}"/>${hair}<circle cx="35" cy="35" r="1.8" fill="#222"/><circle cx="45" cy="35" r="1.8" fill="#222"/><path d="M35 42q5 4 10 0" stroke="#222" stroke-width="1.6" fill="none" stroke-linecap="round"/></svg>`}
function stadium(){return `<svg viewBox="0 0 260 90" fill="none" stroke="#fff" stroke-width="3"><path d="M5 88 Q130 -10 255 88"/><path d="M25 88 Q130 10 235 88"/>${[30,55,80,105,130,155,180,205,230].map(x=>`<path d="M${x} 88 L${x} ${88-Math.round(70*Math.sin(Math.PI*(x-5)/250))}"/>`).join('')}<path d="M0 88 H260"/></svg>`}
function confetti(n,cls){const c=['#C4161C','#ffffff','#8a8d93','#8E0F14','#e2e2e5'];return `<div class="${cls}">${Array.from({length:n},(_,i)=>`<i style="left:${(i*37)%100}%;background:${c[i%5]};animation-delay:${(i%7)*.08}s;transform:rotate(${i*29}deg)"></i>`).join('')}</div>`}
function trophy(k,sz,own){const id='g'+k+(own?1:0);const f=own?`url(#${id})`:'#c9cace',st=own?'#7d8088':'#a9abb0';
 const grad=own?`<defs><linearGradient id="${id}" x1="0" x2="1"><stop offset="0" stop-color="#9ea1a8"/><stop offset=".35" stop-color="#ffffff"/><stop offset=".6" stop-color="#cfd1d6"/><stop offset="1" stop-color="#8d9097"/></linearGradient></defs>`:'';
 const rib=own?'#C4161C':'#b7b9be';let b='';
 if(k==='taca')b=`<path d="M22 14h36v6c0 14-8 24-18 26-10-2-18-12-18-26z" fill="${f}" stroke="${st}"/><path d="M22 18c-10 0-12 14 2 18M58 18c10 0 12 14-2 18" fill="none" stroke="${st}" stroke-width="3"/><rect x="36" y="46" width="8" height="10" fill="${f}" stroke="${st}"/><path d="M28 56h24l3 8H25z" fill="${f}" stroke="${st}"/><rect x="22" y="64" width="36" height="12" rx="1" fill="${rib}"/><rect x="26" y="68" width="28" height="3" fill="#fff" opacity=".5"/>`;
 else if(k==='alta')b=`<path d="M30 4h20l-2 30c0 6-3 10-8 11-5-1-8-5-8-11z" fill="${f}" stroke="${st}"/><path d="M30 10c-6 0-7 10 0 13M50 10c6 0 7 10 0 13" fill="none" stroke="${st}" stroke-width="2.5"/><rect x="37" y="45" width="6" height="8" fill="${f}" stroke="${st}"/><path d="M31 53h18l2 5H29z" fill="${f}" stroke="${st}"/><path d="M26 58h28v18H26z" fill="${rib}"/><path d="M29 62h22M29 66h22M29 70h22" stroke="#fff" opacity=".45"/>`;
 else b=`<circle cx="40" cy="20" r="15" fill="${f}" stroke="${st}"/><path d="M27 15h26M25 22h30M29 29h22M40 5c-6 6-6 24 0 30M40 5c6 6 6 24 0 30" fill="none" stroke="${st}" stroke-width="1.2"/><path d="M33 34c2 8 2 14-2 20h18c-4-6-4-12-2-20" fill="${f}" stroke="${st}"/><path d="M28 54h24l3 6H25z" fill="${f}" stroke="${st}"/><rect x="24" y="60" width="32" height="16" rx="1" fill="${rib}"/><rect x="28" y="65" width="24" height="3" fill="#fff" opacity=".5"/>`;
 return `<svg width="${sz}" height="${sz}" viewBox="0 0 80 80">${grad}${b}</svg>`}
function cardNo(cid){return String(Object.keys(CARDS).indexOf(cid)+1).padStart(2,'0')}
/* ---------- regras ---------- */
function award(aid,cid){const a=A(aid);if(a.cards.some(c=>c.id===cid))return false;a.cards.push({id:cid,d:TODAY});(S.reveal[aid]=S.reveal[aid]||[]).push(cid);S.notifs.push({id:uid(),aid,aud:'atleta',text:'Novo card no seu álbum: '+CARDS[cid].t+'.',seen:false});return true}
function toast(m){V.toast=m;render();clearTimeout(toast.t);toast.t=setTimeout(()=>{V.toast=null;render()},2800)}
function log(who,t){S.audit.unshift({d:TODAY,who,t})}
function allNodes(a){return a.trilha.reduce((r,p)=>r.concat(p.n),[])}
function nextNode(a){return allNodes(a).find(n=>!a.done.includes(n.id))}
function visEv(a){return S.events.filter(e=>e.kind==='treino'?e.partner===a.partner:e.kind==='macro'?e.cats.includes(a.cat):e.kind==='comp'?e.partners.includes(a.partner):e.kind==='conv'?(e.who.includes(a.id)&&e.rel):false).sort((x,y)=>x.d.localeCompare(y.d)||x.h.localeCompare(y.h))}
function nextEv(a){return visEv(a).find(e=>e.d>=TODAY)}
function consentOk(a){return a.consent.termo==='v1.1'&&!a.consent.pendUpd&&a.consent.sinais}
function myAth(){const c=T(V.cid);return S.athletes.filter(a=>a.partner===c.partner)}
function hasKey(key,cid){const [t,id]=key.split(':');return t==='a'?A(id).courses[cid]:S.extraCourses[id+':'+cid]}
function grant(key,cid){const [t,id]=key.split(':');if(t==='a')A(id).courses[cid]={les:[]};else S.extraCourses[id+':'+cid]={les:[]}}
function pendBuy(aid,cid){return S.reqs.find(r=>r.kind==='compra'&&r.aid===aid&&r.cid===cid&&r.status==='pend')}
/* ---------- UI base ---------- */
function render(){if(V.role==='atleta'&&!V.modal&&(S.reveal[V.aid]||[]).length)V.modal={k:'reveal',c:S.reveal[V.aid][0]};const y=(document.querySelector('.ph-body')||{}).scrollTop||0;const ym=window.scrollY;const key=[V.role,V.aid,V.cid,V.tab[V.role],V.page,V.form.pSel,V.form.dAth].join('|');const el=document.getElementById('app');el.className=key!==V._k?'anim':'';V._k=key;el.innerHTML=body()+demoHtml()+modalHtml()+(V.burst?confetti(40,'burst'):'')+(V.toast?`<div class="toast">${esc(V.toast)}</div>`:'');const pb=document.querySelector('.ph-body');if(pb)pb.scrollTop=y;window.scrollTo(0,ym)}
function demoHtml(){return `<button class="demo" data-act="demo" title="Modo demonstração">${ic('eye',16)}</button>`+(V.demo?`<div class="demop"><div class="dh"><b>Modo demonstração</b><button data-act="demo">✕</button></div><p class="mut sm">Dados fictícios. Escolha quem está usando:</p>${topBar()}</div>`:'')}
function topBar(){const R=[['atleta','Atleta'],['resp','Responsável'],['trn','Treinador / Dono'],['saci','SACI admin']];
 let act='';
 if(V.role==='atleta'||V.role==='resp')act=`<select data-chg="actor">${S.athletes.map(a=>`<option value="${a.id}" ${a.id===V.aid?'selected':''}>${V.role==='resp'?'Resp. de ':''}${a.name} (${a.cat}${a.id==='a1'?' · Seleção':''})</option>`).join('')}</select>`;
 if(V.role==='trn')act=`<select data-chg="actor">${S.coaches.map(c=>`<option value="${c.id}" ${c.id===V.cid?'selected':''}>${c.name}${c.dono?' (dono)':''} · ${P(c.partner).name}</option>`).join('')}</select>`;
 return `<div class="bar"><div class="seg">${R.map(r=>`<button class="${V.role===r[0]?'on':''}" data-act="role" data-v="${r[0]}">${r[1]}</button>`).join('')}</div>${act}<button class="lk" data-act="about">Sobre / limitações</button><button class="lk" data-act="reset">Reiniciar demo</button></div>`}
function body(){if(V.role==='atleta')return `<div class="stage">${phone(A(V.aid),'atleta')}</div>`;if(V.role==='resp')return `<div class="stage">${phone(A(V.aid),'resp')}</div>`;if(V.role==='trn')return webTrn();return webSaci()}
const ACT={};
document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el||el.disabled)return;const f=ACT[el.dataset.act];if(f)f(el.dataset,el)});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.f)V.form[el.dataset.f]=el.type==='checkbox'?el.checked:el.value});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.f){V.form[el.dataset.f]=el.type==='checkbox'?el.checked:el.value;if(el.dataset.r)render()}if(el.dataset.chg)ACT[el.dataset.chg](el.dataset,el)});
ACT.demo=()=>{V.demo=!V.demo;render()};
ACT.role=d=>{V.role=d.v;V.demo=false;V.modal=null;V.form={};render()};
ACT.actor=(d,el)=>{V.demo=false;if(V.role==='trn')V.cid=el.value;else V.aid=el.value;V.modal=null;V.form={};render()};
ACT.reset=()=>{S=initState();S.reveal={a1:['CV1']};V.role='atleta';V.aid='a1';V.cid='tr1';V.tab={atleta:'inicio',resp:'inicio',trn:'turma',saci:'painel'};V.page='comp';V.demo=false;V.burst=false;V.modal=null;V.form={};render();toast('Demo reiniciada: cursos, cards e pedidos voltaram ao início')};
ACT.tab=d=>{V.tab[d.r]=d.v;V.form={};render()};
ACT.close=()=>{V.modal=null;render()};
ACT.seen=d=>{const n=S.notifs.find(x=>x.id===d.id);if(n)n.seen=true;render()};
/* ---------- celular (atleta / responsável) ---------- */
function phone(a,mode){const tabs=[['inicio','home','Início'],['album','album','Álbum'],['trilha','trail','Trilha'],['cursos','book','Cursos'],['agenda','cal','Agenda']];if(mode==='resp')tabs.push(['aprov','shield','Aprovar']);
 const t=V.tab[mode];const fn={inicio:vInicio,album:vAlbum,trilha:vTrilha,cursos:vCursos,agenda:vAgenda,aprov:vAprov}[t];
 const pend=mode==='resp'?S.reqs.filter(r=>r.aid===a.id&&(r.kind==='compra'||r.kind==='conv')&&r.status==='pend').length+(a.consent.pendUpd?1:0):0;
 return `<div class="phone ${isPlay(a)?'th-play':'th-sport'}"><div class="ph-top"><b>${mode==='resp'?'Colorado · Família':'Colorado'}</b><span>${mode==='resp'?'Acompanhando '+esc(a.name.split(' ')[0]):esc(a.name.split(' ')[0])}</span></div><div class="ph-body">${fn(a,mode)}</div><nav class="tabs">${tabs.map(x=>`<button class="${t===x[0]?'on':''}" data-act="tab" data-r="${mode}" data-v="${x[0]}">${ic(x[1],22)}${x[2]}${x[0]==='aprov'&&pend?'<span class="dot"></span>':''}</button>`).join('')}</nav></div>`}
function ccHtml(cid,own,tag){const c=CARDS[cid],pg=PAGES.find(p=>p.id===c.p);return `<div class="cc ${own?'on':'off'} ${cid==='CV1'?'sel':''}"><div class="ct"><span>#${cardNo(cid)}</span><span>${pg.t}</span></div>${c.tr?`<div class="tro">${trophy(c.tr,64,own)}</div>`:`<div class="ce">${ic(own?pg.ico:'lock',own?26:18)}</div>`}<b>${esc(c.t)}</b>${c.yr?`<span class="yr">${c.yr}</span>`:''}<small>${tag}</small></div>`}
function cardTile(cid,a){const c=CARDS[cid],h=a.cards.find(x=>x.id===cid);
 return `<button style="display:block;width:100%;padding:0" data-act="cardinfo" data-c="${cid}" data-a="${a.id}">${ccHtml(cid,h,h?fd(h.d):esc(c.h))}</button>`}
function vInicio(a,mode){
 const ns=S.notifs.filter(n=>n.aid===a.id&&n.aud===(mode==='resp'?'resp':'atleta')&&!n.seen);
 const nn=nextNode(a),ev=nextEv(a);const last=a.cards.length?a.cards[a.cards.length-1]:null;
 const nl=nn?(nn.k==='quiz'?QUIZ[nn.id].t:nn.t):null;
 return `${ns.map(n=>`<div class="note">${ic('bell',16)}<span>${esc(n.text)}</span><button data-act="seen" data-id="${n.id}">Ok</button></div>`).join('')}
 <div class="hero2 ${a.cards.some(c=>c.id==='CV1')?'sel':''}"><div class="stad">${stadium()}</div><div class="hrow">${avatar(a,74)}<div><div class="nm">${esc(a.name)}</div><div class="hsub">${esc(a.pos)} · ${a.cat} · ${a.mod}</div>${a.cards.some(c=>c.id==='CV1')?'<span class="selb">★ Seleção Colorada</span>':`<span class="selb" style="background:rgba(255,255,255,.18);color:#fff">${mode==='resp'?'Família colorada':'Vamo, Colorado!'}</span>`}</div></div></div>
 <div class="chips"><span>Posição: ${esc(a.pos)}</span><span>Perna: ${esc(a.foot)}</span><span>${a.cat} · ${a.mod}</span><span>${esc(P(a.partner).name)}</span></div>
 <div class="tiles">${[['ball',a.stats.treinos,'Treinos'],['cal',a.stats.eventos,'Eventos'],['star',a.stats.missoes,'Missões'],['album',a.cards.length,'Cards']].map(t=>`<div class="tile">${ic(t[0],16)}<b>${t[1]}</b><small>${t[2]}</small></div>`).join('')}</div>
 <div class="card"><h4>Constância da semana</h4><div class="wk">${Array.from({length:a.week.goal},(_,i)=>`<i class="${i<a.week.done?'f':''}"></i>`).join('')}</div><div class="sub">${a.week.done} de ${a.week.goal}. Sem pressão: a semana nova começa segunda.</div></div>
 <div class="card hl"><h4>Próxima missão</h4>${nn?`<div class="big">${esc(nl)}</div>${mode==='atleta'?`<p style="margin-top:8px"><button class="btn s" data-act="tab" data-r="atleta" data-v="trilha">Ir para a trilha</button></p>`:''}`:'<div class="big">Trilha completa! Novas missões chegam em breve.</div>'}</div>
 <div class="card"><h4>Próximo evento</h4>${ev?`<div class="big">${esc(ev.t)}</div><div class="sub">${fd(ev.d)} · ${ev.h} · ${esc(ev.pl)}</div>`:'<div class="sub">Nenhum evento marcado.</div>'}</div>
 <div class="card"><h4>Último card</h4>${last?`<div class="big">${esc(CARDS[last.id].t)}</div><div class="sub">${fd(last.d)}</div>`:'<div class="sub">Seu primeiro card vem logo!</div>'}</div>`}
function vAlbum(a){const has=a.cards.some(c=>c.id==='CV1');const pgs=PAGES.filter(p=>p.id!=='col'||has);if(!pgs.some(p=>p.id===V.page))V.page='comp';
 const ids=Object.keys(CARDS).filter(k=>CARDS[k].p===V.page&&(V.page!=='col'||a.cards.some(c=>c.id===k)));
 const done=ids.filter(k=>a.cards.some(c=>c.id===k)).length;
 return `<div class="ptabs">${pgs.map(p=>`<button class="${V.page===p.id?'on':''}" data-act="page" data-v="${p.id}">${p.t}</button>`).join('')}</div><div class="sub" style="margin:4px 0 4px">${done} de ${ids.length} nesta página · sem ranking, sem prazo</div><div class="prog"><i style="width:${ids.length?done/ids.length*100:0}%"></i></div><div class="grid">${ids.map(k=>cardTile(k,a)).join('')}</div>`}
ACT.page=d=>{V.page=d.v;render()};
ACT.cardinfo=d=>{V.modal={k:'card',c:d.c,a:d.a};render()};
function vTrilha(a,mode){const cur=nextNode(a);
 let k=0;return (mode==='resp'?'<div class="sub" style="margin:10px 0 0">Visão do responsável: acompanhe, sem responder pelo atleta.</div>':'')+a.trilha.map((ph,pi)=>`<div><div class="phz"><b>Fase ${pi+1}</b><span>${esc(ph.t.replace(/^Fase \d+ · /,''))}</span></div><div class="zig">${ph.n.map(n=>{const pos=[0,1,2,1][k++%4];
  const done=a.done.includes(n.id),isCur=cur&&cur.id===n.id;
  const pend=n.k==='des'&&S.reqs.some(r=>r.kind==='valida'&&r.aid===a.id&&r.nid===n.id&&r.status==='pend');
  const st=done?'done':isCur?'cur':'fut';const lb=n.k==='quiz'?QUIZ[n.id].t:n.t;
  const sb=done?'Concluída':pend?'Aguardando o treinador':n.k==='quiz'?'Quiz · 2 a 5 min':'Desafio com a bola · o treinador valida';
  return `<div class="zn ${st} p${pos}"><button class="orb" ${st!=='cur'||mode==='resp'||pend?'disabled':''} data-act="node" data-id="${n.id}">${ic(done?'check':st==='fut'?'lock':n.k==='quiz'?'star':'ball',24)}</button><div class="lb"><b>${esc(lb)}</b><small>${sb}</small></div></div>`}).join('')}</div></div>`).join('')}
ACT.node=d=>{const a=A(V.aid),n=allNodes(a).find(x=>x.id===d.id);if(n.k==='quiz'){V.modal={k:'quiz',qid:n.id,i:0,picked:null,ans:[]};render()}else{S.reqs.push({id:uid(),kind:'valida',aid:a.id,nid:n.id,card:n.card,t:n.t,status:'pend'});toast('Pedido enviado ao seu treinador')}};
function quizM(){const m=V.modal,q=QUIZ[m.qid],qq=q.qs[m.i],ord=[0,1,2].map(k=>(k+m.i+1)%3);
 return `<h3>${esc(q.t)}</h3><div class="sub">Pergunta ${m.i+1} de ${q.qs.length}</div><p style="margin:10px 0;font-weight:600">${esc(qq.q)}</p>${ord.map(k=>{let cl='';if(m.picked!=null){if(k===0)cl='ok';else if(k===m.picked)cl='no'}return `<button class="opt ${cl}" ${m.picked!=null?'disabled':''} data-act="qans" data-k="${k}">${esc(qq.o[k])}</button>`}).join('')}${m.picked!=null?`${(()=>{const pl=isPlay(A(V.aid));return m.picked===0?`<div class="cele ok">${confetti(24,'conf')}<b>${pl?'Feitoooo!':'Golaço.'}</b><span>${pl?'Isso!':'Resposta certa.'}</span></div>`:`<div class="cele no"><b>${pl?'Uhhh…':'Na trave.'}</b><span>${pl?'quase! ':''}A resposta era: ${esc(qq.o[0])}.</span></div>`})()}<button class="btn" data-act="qnext">${m.i+1<q.qs.length?'Próxima':'Concluir missão'}</button>`:''}`}
ACT.qans=d=>{const m=V.modal;if(m.picked!=null)return;m.picked=+d.k;m.ans.push(+d.k===0);render()};
ACT.qnext=()=>{const m=V.modal,q=QUIZ[m.qid],a=A(V.aid);if(m.i+1<q.qs.length){m.i++;m.picked=null;render();return}
 if(!a.done.includes(m.qid)){a.done.push(m.qid);a.stats.missoes++;a.week.done=Math.min(a.week.goal,a.week.done+1)}
 const got=[];if(award(a.id,'G6'))got.push('Primeira missão');if(m.ans.every(x=>x)&&award(a.id,'G5'))got.push('Quiz perfeito');V.modal=null;V.burst=true;setTimeout(()=>{V.burst=false;render()},1800);toast('Missão concluída!')};
function vCursos(a,mode){const aud=mode==='resp'?'familia':'atleta';const key=mode==='resp'?'a:'+a.id:'a:'+a.id;
 return `<div class="sub" style="margin:6px 0">${mode==='resp'?'Para a família':'Para você'}</div><div class="crs">${COURSES.filter(c=>c.aud===aud).map(c=>{const h=hasKey(key,c.id),pb=pendBuy(a.id,c.id);const tot=c.les.length,dn=h?h.les.length:0;
  let btn;if(h&&dn>=tot&&tot)btn='<span class="tag g">Concluído</span>';else if(h)btn=`<button class="btn s" data-act="copen" data-c="${c.id}" data-m="${mode}">Continuar</button>`;else if(pb)btn='<span class="tag y">Aguardando o responsável</span>';else if(c.price&&mode==='atleta')btn=`<button class="btn s o" data-act="cbuy" data-c="${c.id}" data-m="${mode}">Pedir ao responsável</button>`;else btn=`<button class="btn s" data-act="cbuy" data-c="${c.id}" data-m="${mode}">${c.price?'Comprar':'Começar'}</button>`;
  return `<div class="card" style="margin:0"><div class="row"><div><div class="big">${esc(c.t)}</div><div class="sub">${esc(c.d)}</div></div><span class="price">${brl(c.price)}</span></div>${h?`<div class="bar2"><i style="width:${tot?dn/tot*100:0}%"></i></div>`:''}<div style="margin-top:8px">${btn}</div></div>`}).join('')}</div>`}
ACT.copen=d=>{const key=d.k||'a:'+V.aid;V.modal={k:'course',cid:d.c,key};render()};
ACT.cbuy=d=>{const a=A(V.aid),c=COURSES.find(x=>x.id===d.c),key='a:'+a.id;
 if(c.price&&d.m==='atleta'){S.reqs.push({id:uid(),kind:'compra',aid:a.id,cid:c.id,status:'pend'});S.notifs.push({id:uid(),aid:a.id,aud:'resp',text:a.name.split(' ')[0]+' quer o curso "'+c.t+'" ('+brl(c.price)+'). Aguarda sua aprovação.',seen:false});toast('Pedido enviado ao seu responsável')}
 else{grant(key,c.id);V.modal={k:'course',cid:c.id,key};render()}};
function ytId(u){const x=String(u).match(/(?:youtu\.be\/|v=|embed\/|shorts\/)([\w-]{11})/);return x?x[1]:null}
function vidHtml(key){const u=VIDEOS[key],id=u&&ytId(u);
 if(id)return `<div class="vid"><iframe src="https://www.youtube-nocookie.com/embed/${id}?rel=0&modestbranding=1" title="Vídeo da aula" allow="accelerometer; encrypted-media; picture-in-picture" allowfullscreen></iframe></div>`;
 return `<div class="vid"><video controls playsinline preload="metadata" src="videos/${key}.mp4" onerror="this.parentNode.innerHTML=document.getElementById('vph').innerHTML"></video></div>`}
function courseM(){const m=V.modal,c=COURSES.find(x=>x.id===m.cid),h=hasKey(m.key,c.id)||{les:[]};
 if(m.les!=null){const i=m.les,k=c.id+'-'+(i+1);return `<button class="lk2" data-act="lesback">← ${esc(c.t)}</button><div class="sub" style="margin-top:6px">Aula ${i+1} de ${c.les.length}</div><h3>${esc(c.les[i])}</h3>${vidHtml(k)}<p style="margin-top:12px">${h.les.includes(i)?'<span class="tag g">Aula concluída</span> <button class="btn g s" data-act="lesback">Voltar</button>':`<button class="btn" data-act="clesson" data-i="${i}">Concluir aula</button>`}</p>`}
 return `<h3>${esc(c.t)}</h3><div class="sub">${esc(c.d)}</div>${c.unlock?'<div class="panel">Ao concluir as aulas, o guia de sinais é liberado no seu painel.</div>':''}${c.les.map((l,i)=>`<button class="les ${h.les.includes(i)?'ok':''}" data-act="lesopen" data-i="${i}"><span class="pl">${ic(h.les.includes(i)?'check':'play',18)}</span><span><b>Aula ${i+1}: ${esc(l)}</b><small>${h.les.includes(i)?'Concluída · rever':'Vídeo · 3 a 6 min'}</small></span></button>`).join('')}<p style="margin-top:10px"><button class="btn g" data-act="close">Fechar</button></p>`}
ACT.lesopen=d=>{V.modal.les=+d.i;render()};ACT.lesback=()=>{V.modal.les=null;render()};
ACT.clesson=d=>{const m=V.modal,c=COURSES.find(x=>x.id===m.cid),h=hasKey(m.key,c.id);const i=+d.i;if(!h.les.includes(i))h.les.push(i);m.les=null;{const [t0,id0]=m.key.split(':');if(t0==='a'&&c.id==='k_boas'&&i===0){['H1','H2','H3'].forEach(x=>award(id0,x));V.modal=null;render();return}}
 if(h.les.length>=c.les.length){const [t,id]=m.key.split(':');if(t==='a'){const ok=c.aud==='atleta'&&award(id,'G4');toast('Curso concluído!'+(ok?' Novo card: Curso concluído':''))}else if(c.unlock){T(id).modulo=true;log(T(id).name,'Concluiu módulo: leitura de jogo básico');toast('Módulo concluído. O guia de sinais foi liberado.')}else toast('Curso concluído!')}else render()};
function vAgenda(a,mode){const evs=visEv(a),kinds={treino:'Treino',macro:'Evento do Inter',comp:'Competição',conv:'Convocação'};
 return `<div class="sub" style="margin:6px 0">Próximos compromissos</div>`+evs.map(e=>{const r=S.rsvp[e.id+a.id];const rs=e.kind==='treino'?'':(mode==='resp'||e.kind==='conv'?(r?`<span class="tag ${r==='vou'?'g':''}">${r==='vou'?'Vai':'Não vai'}</span>`:''):`<button class="btn s ${r==='vou'?'':'o'}" data-act="rsvp" data-e="${e.id}" data-v="vou">Vou</button> <button class="btn s ${r==='nao'?'':'o'}" data-act="rsvp" data-e="${e.id}" data-v="nao">Não vou</button>`);
  const rr=mode==='resp'&&e.kind!=='treino'?`<button class="btn s o" data-act="rsvp" data-e="${e.id}" data-v="${r==='vou'?'nao':'vou'}">${r==='vou'?'Marcar não vai':'Confirmar presença'}</button>`:rs;
  return `<div class="card"><div class="ev"><div class="dt"><b>${dd(e.d)}</b><small>${mm(e.d)}</small></div><div><div class="big">${esc(e.t)}</div><div class="sub">${e.h} · ${esc(e.pl)}</div><div style="margin:4px 0"><span class="tag ${e.kind==='conv'?'r':''}">${kinds[e.kind]}</span>${e.card?'<span class="tag y">Rende um card</span>':''}${e.closed&&S.rsvp[e.id+a.id]==='vou'?'<span class="tag g">Card entregue</span>':''}</div>${rr}</div></div></div>`}).join('')||'<div class="sub">Nada marcado.</div>'}
ACT.rsvp=d=>{S.rsvp[d.e+V.aid]=d.v;render()};
function vAprov(a){const mine=S.reqs.filter(r=>r.aid===a.id);
 const pend=mine.filter(r=>r.status==='pend'&&(r.kind==='compra'||r.kind==='conv'));
 const ns=S.notifs.filter(n=>n.aid===a.id&&n.aud==='resp'&&!n.seen);
 return `${ns.map(n=>`<div class="note">${ic('bell',16)}<span>${esc(n.text)}</span><button data-act="seen" data-id="${n.id}">Ok</button></div>`).join('')}
 <div class="card"><h4>Para aprovar</h4>${pend.length?pend.map(r=>r.kind==='compra'?`<div style="margin:8px 0"><div class="big">${esc(COURSES.find(c=>c.id===r.cid).t)}</div><div class="sub">${brl(COURSES.find(c=>c.id===r.cid).price)} · pedido de ${esc(a.name.split(' ')[0])}</div><p style="margin-top:6px"><button class="btn s" data-act="appr" data-id="${r.id}">Aprovar</button> <button class="btn s o" data-act="deny" data-id="${r.id}">Recusar</button></p></div>`:`<div style="margin:8px 0"><div class="big">Convocação: ${esc(r.title)}</div><div class="sub">Comunicado do Inter · ${fd(r.date)}. Ao liberar, o card aparece no álbum do atleta.</div><p style="margin-top:6px"><button class="btn s" data-act="rel" data-id="${r.id}">Liberar ao atleta</button></p></div>`).join(''):'<div class="sub">Nada pendente.</div>'}</div>
 <div class="card"><h4>Consentimento</h4><div class="big">Termo ${a.consent.termo} · aceito em ${fd(a.consent.d)}</div>${a.consent.pendUpd?`<div class="panel w sm" style="margin-top:6px">Termo v1.2 aguarda seu aceite: inclui o registro de altura e a observação de maturação (podem ser dado de saúde) [Inferência — validar com jurídico]. <p style="margin-top:6px"><button class="btn s" data-act="accept">Aceitar v1.2</button></p></div>`:''}
 <label class="ck"><input type="checkbox" ${a.consent.sinais?'checked':''} data-act="togcons"> Acompanhamento esportivo pelo clube</label></div>
 <div class="card"><h4>Tempo de uso e avisos</h4><div class="fr"><div><label>Limite diário no app</label><select data-chg="limit"><option value="30" ${a.limit==30?'selected':''}>30 min</option><option value="60" ${a.limit==60?'selected':''}>60 min</option><option value="90" ${a.limit==90?'selected':''}>90 min</option></select></div></div><label class="ck"><input type="checkbox" checked> Lembrete de treino (sem cobrança de meta)</label><label class="ck"><input type="checkbox" checked> Aviso de novo card</label></div>
 <div class="card"><h4>Dados do atleta</h4><p class="sub">Você pode pedir uma cópia dos dados registrados (inclui a altura) ou a exclusão da conta.</p>${mine.filter(r=>r.kind==='acesso'||r.kind==='exclusao').map(r=>`<div class="tag ${r.status==='pend'?'y':'g'}">${r.kind==='acesso'?'Cópia dos dados':'Exclusão'}: ${r.status==='pend'?'em análise':'atendida'}</div>`).join('')}<p style="margin-top:8px"><button class="btn s o" data-act="dreq" data-v="acesso">Pedir cópia dos dados</button> <button class="btn s o" data-act="dreq" data-v="exclusao">Excluir conta e dados</button></p></div>`}
ACT.appr=d=>{const r=S.reqs.find(x=>x.id===d.id);r.status='ok';grant('a:'+r.aid,r.cid);S.notifs.push({id:uid(),aid:r.aid,aud:'atleta',text:'Seu responsável liberou o curso "'+COURSES.find(c=>c.id===r.cid).t+'".',seen:false});toast('Curso aprovado e liberado')};
ACT.deny=d=>{const r=S.reqs.find(x=>x.id===d.id);r.status='no';S.notifs.push({id:uid(),aid:r.aid,aud:'atleta',text:'Este curso fica para outra hora. Que tal uma missão da trilha?',seen:false});toast('Pedido recusado')};
ACT.rel=d=>{const r=S.reqs.find(x=>x.id===d.id);r.status='ok';award(r.aid,'CV1');if(!S.funil[r.aid])S.funil[r.aid]={status:'Convocado à Seleção',rev:'2027-04-30'};else S.funil[r.aid].status='Convocado à Seleção';const e=S.events.find(x=>x.id===r.eid);if(e)e.rel=true;log(A(r.aid).resp,'Liberou convocação ao atleta ('+A(r.aid).name+')');toast('Card liberado no álbum do atleta')};
ACT.accept=()=>{const a=A(V.aid);a.consent.termo='v1.1';a.consent.pendUpd=false;a.consent.d=TODAY;log(a.resp,'Aceitou termo atualizado ('+a.name+')');toast('Termo aceito')};
ACT.togcons=()=>{const a=A(V.aid);a.consent.sinais=!a.consent.sinais;log(a.resp,'Alterou acompanhamento esportivo ('+a.name+'): '+(a.consent.sinais?'ativo':'desativado'));render()};
ACT.limit=(d,el)=>{A(V.aid).limit=+el.value;toast('Limite de uso atualizado')};
ACT.dreq=d=>{const a=A(V.aid);if(S.reqs.some(r=>r.aid===a.id&&r.kind===d.v&&r.status==='pend')){toast('Pedido já em análise');return}S.reqs.push({id:uid(),kind:d.v,aid:a.id,status:'pend'});log(a.resp,(d.v==='acesso'?'Pediu cópia dos dados':'Pediu exclusão de dados')+' ('+a.name+')');toast('Pedido enviado ao SACI')};
/* ---------- modal ---------- */
function modalHtml(){const m=V.modal;if(!m)return'';let h='';
 if(m.k==='quiz')h=quizM();else if(m.k==='course')h=courseM();
 else if(m.k==='card'){const c=CARDS[m.c],a=A(m.a),own=a.cards.find(x=>x.id===m.c);h=`<div class="flip" style="margin-bottom:10px">${ccHtml(m.c,own,own?fd(own.d):'')}</div><h3>${esc(c.t)}</h3><p class="sub">Página: ${PAGES.find(p=>p.id===c.p).t}</p><p style="margin:10px 0">${c.txt?esc(c.txt)+'<br>':''}${own?(m.c==='CV1'?'O Inter convocou você para a Seleção. Parabéns!':'Conquistado em '+fd(own.d)+'.'):'Como conseguir: '+esc(c.h)+'.'}</p><button class="btn g" data-act="close">Fechar</button>`}
 else if(m.k==='alt'){h=`<h3>Registrar altura</h3><p class="sub">${esc(A(m.aid).name)} · visível só para você, SACI e formação. Não aparece para o atleta.</p><div class="fr"><div><label>Altura (cm)</label><input type="number" step="0.1" data-f="altCm" placeholder="ex.: 152"></div></div><p class="mut">Data: ${fd(TODAY)} · medido por ${esc(T(V.cid).name)}</p><p style="margin-top:10px"><button class="btn" data-act="altsave" data-a="${m.aid}">Salvar</button> <button class="btn g" data-act="close">Cancelar</button></p>`}
 else if(m.k==='about')h=aboutM();
 else if(m.k==='reveal'){const c=CARDS[m.c];h=`<div class="reveal">${confetti(30,'conf')}<div class="sub">${m.c==='CV1'?'Comunicado do Inter':'Card novo!'}</div><div class="flip">${ccHtml(m.c,true,fd(TODAY))}</div><h3>${m.c==='CV1'?'Você foi convocado!':esc(c.t)}</h3><p class="sub" style="margin:4px 0 14px">${m.c==='CV1'?'Agora você faz parte da Seleção Colorada.':'Guardado na página '+PAGES.find(p=>p.id===c.p).t+' do seu álbum.'}</p><button class="btn" data-act="revok">${(S.reveal[V.aid]||[]).length>1?'Próximo card':'Guardar no álbum'}</button></div>`}
 return `<div class="modal"><div>${h}</div></div>`}
document.addEventListener('click',e=>{if(e.target.classList.contains('modal')&&V.modal&&V.modal.k!=='quiz'){V.modal=null;render()}});
ACT.revok=()=>{const q=S.reveal[V.aid]||[];q.shift();const n=S.notifs.find(x=>x.aid===V.aid&&x.aud==='atleta'&&!x.seen&&/card/i.test(x.text));if(n)n.seen=true;V.modal=null;render()};
ACT.about=()=>{V.modal={k:'about'};render()};
function aboutM(){return `<h3>Sobre este protótipo</h3><p class="sub">Modelo para a startup. Dados fictícios, estado só na memória (recarregar reinicia).</p>
 <h3 style="font-size:14px">Limitações e pontos abertos</h3>
 <ul style="padding-left:18px" class="sm"><li>Tela do responsável: forma final (login próprio) a definir no desenvolvimento. [Inferência]</li><li>Altura e maturação podem ser dado de saúde: validar termo e acesso com jurídico. [Inferência]</li><li>Indicação sem evidência: mais simples para o treinador, mas a confirmação pelo SACI no evento passa a ser o único filtro. Critério mínimo (2 de jogo + 1 de aprendizagem/atitude) a calibrar. [Inferência]</li><li>Troféus: desenhos originais inspirados, não réplicas das taças oficiais (que pertencem às entidades organizadoras). Títulos e anos: [Verificado — histórico do clube].</li><li>Vídeos: links do YouTube ou arquivos em videos/ precisam de direito de uso; canal oficial do Inter é a fonte indicada.</li><li>Elementos do Inter: só cores, listras e estádio genérico; escudo e mascote oficiais dependem de autorização do clube.</li><li>Aplicação do ECA Digital (Lei 15.211/2025) a esta web app: revisão jurídica. [Verificado — texto do PIDA/BC-V3; aplicação concreta: Inferência]</li><li>Quem valida os desafios de fundamentos no Inter e preços dos cursos: em aberto. [Especulação]</li><li>Sem login, sem push, sem pagamento real; notificações simuladas.</li><li>Formação (observador da Seleção) não tem tela própria aqui: usa a visão do funil do SACI.</li></ul><p style="margin-top:10px"><button class="btn g" data-act="close">Fechar</button></p>`}
/* ---------- treinador / dono ---------- */
function webTrn(){const c=T(V.cid),t=V.tab.trn;const tabs=[['turma','Turma'],['pres','Presença'],['comp','Competições'],['des','Desafios'],['dest','Indicar'],['crs','Cursos']];if(c.dono)tabs.push(['proj','Meu projeto']);
 const fn={turma:tTurma,pres:tPres,comp:tComp,des:tDes,dest:tDest,crs:tCrs,proj:tProj}[t];
 return `<div class="web"><div class="side">${tabs.map(x=>`<button class="${t===x[0]?'on':''}" data-act="tab" data-r="trn" data-v="${x[0]}">${x[1]}</button>`).join('')}</div><div class="main"><div class="mut" style="margin-bottom:6px">${esc(c.name)} · ${esc(P(c.partner).name)}${c.dono?' · dono do projeto':''}</div>${fn(c)}</div></div>`}
function tTurma(c){const as=myAth();return `<h2>Turma</h2><div class="tw"><table><tr><th>Atleta</th><th>Cat.</th><th>Posição / perna</th><th>Treinos</th><th>Consent.</th><th>Altura (a sua)</th></tr>${as.map(a=>{const h=a.altura.filter(x=>x.by===c.name).slice(-1)[0];return `<tr><td>${avatar(a,30)} ${esc(a.name)}</td><td>${a.cat}</td><td>${esc(a.pos)} · ${esc(a.foot)}</td><td>${a.stats.treinos}</td><td>${consentOk(a)||(a.consent.termo==='v1.1'&&!a.consent.pendUpd)?'<span class="tag g">ok</span>':'<span class="tag y">pendência</span>'}</td><td>${h?h.cm+' cm <span class="mut sm">('+fd(h.d)+')</span>':'—'} <button class="btn s o" data-act="altopen" data-a="${a.id}">Registrar</button></td></tr>`}).join('')}</table></div><div class="panel">Altura é contexto: não aparece para o atleta e você vê só as que registrou. A maturação tardia agora entra como opção dentro de <b>Indicar</b>.</div>`}
ACT.altopen=d=>{V.modal={k:'alt',aid:d.a};V.form={};render()};
ACT.altsave=d=>{const v=parseFloat(V.form.altCm);if(!v||v<60||v>230){toast('Informe uma altura válida em cm');return}const a=A(d.a),c=T(V.cid);a.altura.push({d:TODAY,cm:v,by:c.name});log(c.name,'Registrou altura ('+a.name+')');V.modal=null;V.form={};toast('Altura registrada')};
ACT.mat=(d,el)=>{const a=A(d.a);a.mat=el.value;log(T(V.cid).name,'Observação de maturação atualizada ('+a.name+')');toast('Observação salva')};
function nextTreino(c){return S.events.filter(e=>e.kind==='treino'&&e.partner===c.partner&&e.d>=TODAY).sort((x,y)=>x.d.localeCompare(y.d))[0]}
function tPres(c){const e=nextTreino(c),as=myAth();if(!e)return '<h2>Presença</h2><p class="mut">Sem treino marcado.</p>';const done=S.pres[e.id];
 return `<h2>Presença</h2><p><b>${esc(e.t)}</b> · ${fd(e.d)} ${e.h}</p>${done?'<div class="panel">Presença já lançada neste treino.</div>':`${as.map(a=>`<label class="ck"><input type="checkbox" data-f="p_${a.id}" ${V.form['p_'+a.id]===false?'':'checked'}> ${esc(a.name)} <span class="mut sm">(${a.cat})</span></label>`).join('')}<p style="margin-top:10px"><button class="btn" data-act="plan" data-e="${e.id}">Lançar presença</button></p>`}`}
ACT.plan=d=>{const as=myAth();let n=0;as.forEach(a=>{if(V.form['p_'+a.id]===false)return;a.stats.treinos++;a.week.done=Math.min(a.week.goal,a.week.done+1);n++;award(a.id,'G1');if(a.stats.treinos>=10)award(a.id,'G2')});S.pres[d.e]=true;log(T(V.cid).name,'Lançou presença ('+n+' atletas)');V.form={};toast('Presença lançada: '+n+' atletas')};
function tComp(c){const as=myAth();return `<h2>Competições</h2><p class="mut">Registre uma competição e os atletas que jogaram: o card entra no álbum.</p><div class="fr"><div><label>Competição</label><select data-f="cmp">${COMP_OPTS.map(k=>`<option value="${k}" ${V.form.cmp===k?'selected':''}>${CARDS[k].t}</option>`).join('')}</select></div></div>${as.map(a=>`<label class="ck"><input type="checkbox" data-f="c_${a.id}" ${V.form['c_'+a.id]?'checked':''}> ${esc(a.name)}</label>`).join('')}<p style="margin-top:10px"><button class="btn" data-act="cmpsave">Registrar</button></p>`}
ACT.cmpsave=()=>{const k=V.form.cmp||COMP_OPTS[0];let n=0;myAth().forEach(a=>{if(V.form['c_'+a.id]){a.stats.eventos++;award(a.id,k);n++}});if(!n){toast('Marque ao menos um atleta');return}log(T(V.cid).name,'Registrou competição: '+CARDS[k].t+' ('+n+')');V.form={};toast('Competição registrada: '+n+' atleta(s) com card novo')};
function tDes(c){const as=myAth().map(a=>a.id);const rs=S.reqs.filter(r=>r.kind==='valida'&&as.includes(r.aid)&&r.status==='pend');
 return `<h2>Desafios para validar</h2>${rs.length?rs.map(r=>`<div class="panel"><b>${esc(A(r.aid).name)}</b> · ${esc(r.t)}<p style="margin-top:6px"><button class="btn s" data-act="valid" data-id="${r.id}" data-v="1">Feito</button> <button class="btn s o" data-act="valid" data-id="${r.id}" data-v="0">Ainda não</button></p></div>`).join(''):'<p class="mut">Nenhum desafio aguardando.</p>'}<p class="mut">Binário: feito ou não feito. Sem nota.</p>`}
ACT.valid=d=>{const r=S.reqs.find(x=>x.id===d.id),a=A(r.aid);r.status='ok';if(d.v==='1'){if(!a.done.includes(r.nid))a.done.push(r.nid);award(a.id,r.card);a.stats.missoes++;log(T(V.cid).name,'Validou desafio ('+a.name+')');toast('Desafio validado: card entregue')}else{S.notifs.push({id:uid(),aid:a.id,aud:'atleta',text:'Quase lá! Continue treinando esse desafio e peça de novo quando quiser.',seen:false});toast('Registrado: o atleta pode tentar de novo')}};
function tDest(c){
 if(!c.modulo)return `<h2>Indicar atleta</h2><div class="panel w">Este recurso é liberado depois do módulo <b>Leitura de jogo: básico</b> (gratuito).<p style="margin-top:8px"><button class="btn" data-act="tab" data-r="trn" data-v="crs">Ir para Cursos</button></p></div>`;
 const as=myAth();if(V.form.sent)return `<h2>Indicar atleta</h2><div class="panel">Indicação enviada ao SACI. Você não acompanha o status depois do envio: é assim por desenho.</div><button class="btn" data-act="newdest">Nova indicação</button>`;
 const sel=V.form.dAth;
 if(!sel)return `<h2>Indicar atleta</h2><p class="mut">Disponível para Sub-11 e Sub-13. Escolha o atleta:</p><div class="tw"><table>${as.map(a=>{const el=a.cat==='Sub-11'||a.cat==='Sub-13';return `<tr><td>${avatar(a,30)} ${esc(a.name)}</td><td>${a.cat}</td><td><button class="btn s" ${el?'':'disabled'} data-act="dpick" data-a="${a.id}">Indicar</button>${el?'':' <span class="mut sm">só Sub-11 e Sub-13</span>'}</td></tr>`}).join('')}</table></div>`;
 const a=A(sel);if(!a.consent.sinais||a.consent.pendUpd)return `<h2>Indicar atleta</h2><div class="panel w">Há pendência de consentimento para ${esc(a.name)}. Fale com a família antes de registrar.</div><button class="btn g" data-act="newdest">Voltar</button>`;
 const nsel=SIGNALS.filter(s=>V.form['s_'+s.id]).length;return `<h2>Indicar: ${esc(a.name)} <span class="tag">${a.cat}</span></h2><p class="mut">Toque no que você viu. Sem nota, sem texto: o SACI confirma no próximo evento.</p>${['Jogo','Aprendizagem','Atitude'].map(g=>`<h3>${g}</h3><div>${SIGNALS.filter(s=>s.g===g).map(s=>`<button class="chip ${V.form['s_'+s.id]?'on':''}" data-act="sigt" data-k="s_${s.id}">${esc(s.t)}</button>`).join('')}</div>`).join('')}<h3>Contexto (opcional)</h3><button class="chip ctx ${V.form.mat?'on':''}" data-act="sigt" data-k="mat">Parece amadurecer mais tarde que os colegas</button><p style="margin-top:14px"><button class="btn" data-act="dsend">Indicar ao SACI${nsel?`<span class="cnt" style="background:#fff;color:var(--red)">${nsel}</span>`:''}</button> <button class="btn g" data-act="newdest">Cancelar</button></p>`}
ACT.sigt=d=>{V.form[d.k]=!V.form[d.k];render()};
ACT.dpick=d=>{V.form={dAth:d.a};render()};ACT.newdest=()=>{V.form={};render()};
ACT.dsend=()=>{const a=A(V.form.dAth),c=T(V.cid),obs={};SIGNALS.forEach(s=>{if(V.form['s_'+s.id])obs[s.id]={ev:(V.form['e_'+s.id]||'').trim()}});const ks=Object.keys(obs);
 if(!ks.length){toast('Toque em ao menos um item');return}if(V.form.mat)a.mat='tardia';
 S.signals.push({id:uid(),aid:a.id,tr:c.id,d:TODAY,obs,conf:{}});if(!S.funil[a.id])S.funil[a.id]={status:'Sinalizado',rev:'2027-05-05'};log(c.name,'Indicou atleta ('+a.name+')');V.form={sent:1};render()};
function tCrs(c){const key='c:'+c.id;return `<h2>Cursos para treinadores</h2><div class="crs">${COURSES.filter(x=>x.aud==='treinador').map(x=>{const h=hasKey(key,x.id),dn=h?h.les.length:0;const btn=h?(dn>=x.les.length?'<span class="tag g">Concluído</span>':`<button class="btn s" data-act="copen" data-c="${x.id}" data-k="${key}">Continuar</button>`):`<button class="btn s" data-act="ctbuy" data-c="${x.id}">${x.price?'Adquirir ('+brl(x.price)+')':'Começar'}</button>`;return `<div class="panel"><div style="display:flex;justify-content:space-between;gap:8px"><div><b>${esc(x.t)}</b><div class="mut">${esc(x.d)}</div></div><span class="price" style="color:var(--red);font-weight:700">${brl(x.price)}</span></div><div style="margin-top:8px">${btn}</div></div>`}).join('')}</div><p class="mut">Compra simulada: pagamento real fica para a startup.</p>`}
ACT.ctbuy=d=>{const key='c:'+V.cid;grant(key,d.c);V.modal={k:'course',cid:d.c,key};render()};
function tProj(c){const p=P(c.partner),as=S.athletes.filter(a=>a.partner===p.id),pend=as.filter(a=>!(a.consent.termo==='v1.1'&&!a.consent.pendUpd)).length;
 const n=S.signals.filter(s=>as.some(a=>a.id===s.aid)).length;
 return `<h2>Meu projeto: ${esc(p.name)}</h2><div class="kpis"><div class="kpi"><b>${as.length}</b><small>Atletas</small></div><div class="kpi"><b>${S.coaches.filter(x=>x.partner===p.id).length}</b><small>Treinadores</small></div><div class="kpi"><b>${pend}</b><small>Pendências de consentimento</small></div><div class="kpi"><b>${n}</b><small>Registros enviados ao SACI (só contagem)</small></div></div><h3>Treinadores</h3><table>${S.coaches.filter(x=>x.partner===p.id).map(x=>`<tr><td>${esc(x.name)}</td><td>${x.modulo?'<span class="tag g">Leitura de jogo concluída</span>':'<span class="tag y">Módulo pendente</span>'}</td></tr>`).join('')}</table><h3>Próximos eventos</h3>${S.events.filter(e=>e.d>=TODAY&&(e.partner===p.id||(e.partners||[]).includes(p.id)||e.kind==='macro')).map(e=>`<div>${fd(e.d)} · ${esc(e.t)}</div>`).join('')}<div class="panel">O dono vê contagens e pendências, nunca o status individual do funil.</div>`}
/* ---------- SACI ---------- */
function webSaci(){const t=V.tab.saci,tabs=[['painel','Painel'],['parc','Parceiros'],['atl','Atletas'],['ev','Eventos'],['funil','Funil'],['conv','Convocatórias']];
 const fn={painel:sPainel,parc:sParc,atl:sAtl,ev:sEv,funil:sFunil,conv:sConv}[t];
 return `<div class="web"><div class="side">${tabs.map(x=>`<button class="${t===x[0]?'on':''}" data-act="tab" data-r="saci" data-v="${x[0]}">${x[1]}</button>`).join('')}</div><div class="main">${fn()}</div></div>`}
function sPainel(){const fun=Object.keys(S.funil);const rq=S.reqs.filter(r=>(r.kind==='acesso'||r.kind==='exclusao')&&r.status==='pend');const unc=S.signals.filter(s=>Object.keys(s.obs).some(k=>!s.conf[k]));
 const pc=S.athletes.filter(a=>!(a.consent.termo==='v1.1'&&!a.consent.pendUpd)).length;
 return `<h2>Painel</h2><div class="kpis"><div class="kpi"><b>${S.athletes.length}</b><small>Atletas ativos</small></div><div class="kpi"><b>${S.partners.length}</b><small>Parceiros</small></div><div class="kpi"><b>${fun.length}</b><small>No funil</small></div><div class="kpi"><b>${fun.filter(k=>S.funil[k].status==='Convocado à Seleção').length}</b><small>Convocados</small></div><div class="kpi"><b>${pc}</b><small>Pendências de consentimento</small></div><div class="kpi"><b>${S.counts.archived}</b><small>Arquivados (só contagem)</small></div></div>
 <h3>Pendências</h3>${rq.map(r=>`<div class="panel">${r.kind==='acesso'?'Cópia dos dados':'Exclusão de dados'} · ${esc(A(r.aid).name)} (pedido do responsável) <button class="btn s" data-act="atend" data-id="${r.id}">Marcar como atendida</button></div>`).join('')}${unc.length?`<div class="panel">${unc.length} sinalização(ões) aguardando confirmação no próximo evento. <button class="btn s o" data-act="tab" data-r="saci" data-v="funil">Abrir funil</button></div>`:''}${S.reqs.filter(r=>r.kind==='conv'&&r.status==='pend').map(r=>`<div class="panel">Convocação de ${esc(A(r.aid).name)} aguardando liberação do responsável.</div>`).join('')}${!rq.length&&!unc.length?'<p class="mut">Sem pendências.</p>':''}
 <h3>Próximas oportunidades com parceiros</h3><table>${S.partners.slice().sort((x,y)=>x.proxD.localeCompare(y.proxD)).map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.prox)}</td><td>${fd(p.proxD)}</td></tr>`).join('')}</table>
 <h3>Auditoria recente</h3>${S.audit.slice(0,6).map(x=>`<div class="mut">${fd(x.d)} · ${esc(x.who)}: ${esc(x.t)}</div>`).join('')}`}
ACT.atend=d=>{const r=S.reqs.find(x=>x.id===d.id);r.status='ok';S.notifs.push({id:uid(),aid:r.aid,aud:'resp',text:(r.kind==='acesso'?'Sua cópia dos dados está pronta (simulado).':'Seu pedido de exclusão foi atendido (simulado).'),seen:false});log('SACI','Atendeu pedido do responsável ('+A(r.aid).name+')');toast('Pedido atendido')};
function sParc(){const sel=V.form.pSel&&P(V.form.pSel);if(!sel)return `<h2>Parceiros</h2><div class="tw"><table><tr><th>Parceiro</th><th>Cidade</th><th>Modalidade</th><th>Faixa</th><th>Último contato</th><th></th></tr>${S.partners.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.city)}</td><td>${p.mod}</td><td>${p.faixa}</td><td>${fd(p.ult)}</td><td><button class="btn s o" data-act="psel" data-id="${p.id}">Abrir</button></td></tr>`).join('')}</table></div>`;
 const p=sel;return `<button class="btn g s" data-act="psel" data-id="">← Voltar</button><h2 style="margin-top:8px">${esc(p.name)}</h2><div class="fr"><div><label>Cidade / região</label>${esc(p.city)} / ${esc(p.reg)}</div><div><label>Modalidade</label>${p.mod}</div><div><label>Faixa etária</label>${p.faixa}</div><div><label>Atletas (porte)</label>${p.porte}</div><div><label>Estrutura</label>${esc(p.estr)}</div><div><label>Perfil</label>${esc(p.perfil)}</div><div><label>Forma de relação</label>${esc(p.forma)}</div><div><label>Contato</label>${esc(p.contato)}</div></div><div class="panel"><b>Comportamento:</b> ${esc(p.comp)}<br><b>Capacidade:</b> ${esc(p.cap)}</div>
 <h3>Treinadores e atletas</h3><div>${S.coaches.filter(c=>c.partner===p.id).map(c=>esc(c.name)).join(', ')} · ${S.athletes.filter(a=>a.partner===p.id).map(a=>esc(a.name)+' ('+a.cat+')').join(', ')}</div>
 <h3>Próxima oportunidade</h3><div class="fr"><div><input data-f="pProx" value="${esc(V.form.pProx!=null?V.form.pProx:p.prox)}"></div><div><input type="date" data-f="pProxD" value="${V.form.pProxD||p.proxD}"></div></div><button class="btn s" data-act="psaveprox" data-id="${p.id}">Salvar</button>
 <h3>Histórico</h3>${p.hist.map(h=>`<div class="mut">${fd(h.d)} · <b>${h.tipo}</b>: ${esc(h.n)}</div>`).join('')}<div class="fr"><div><select data-f="hTipo"><option>Visita</option><option>Contato</option><option>Evento</option></select></div><div><input data-f="hNota" placeholder="Anotação"></div></div><button class="btn s" data-act="hadd" data-id="${p.id}">Adicionar registro</button>`}
ACT.psel=d=>{V.form=d.id?{pSel:d.id}:{};render()};
ACT.psaveprox=d=>{const p=P(d.id);if(V.form.pProx!=null)p.prox=V.form.pProx;if(V.form.pProxD)p.proxD=V.form.pProxD;log('SACI','Atualizou próxima oportunidade ('+p.name+')');toast('Salvo')};
ACT.hadd=d=>{const p=P(d.id);if(!(V.form.hNota||'').trim()){toast('Escreva a anotação');return}p.hist.unshift({d:TODAY,tipo:V.form.hTipo||'Visita',n:V.form.hNota.trim()});p.ult=TODAY;V.form.hNota='';log('SACI','Registro em '+p.name);toast('Registro adicionado')};
function sAtl(){return `<h2>Atletas ativos</h2><div class="tw"><table><tr><th>Atleta</th><th>Parceiro</th><th>Cat.</th><th>Mod.</th><th>Treinos</th><th>Altura (último)</th><th>Maturação</th><th>Consent.</th></tr>${S.athletes.map(a=>{const h=a.altura.slice(-1)[0];return `<tr><td>${esc(a.name)}</td><td>${esc(P(a.partner).name)}</td><td>${a.cat}</td><td>${a.mod}</td><td>${a.stats.treinos}</td><td>${h?h.cm+' cm ('+fd(h.d)+')':'—'}</td><td>${MATUR.find(m=>m.v===a.mat).t}</td><td>${a.consent.pendUpd?'<span class="tag y">termo v1.2 pendente</span>':'<span class="tag g">ok</span>'}</td></tr>`}).join('')}</table></div>`}
function sEv(){return `<h2>Eventos</h2>${S.events.filter(e=>e.kind==='macro'||e.kind==='comp').sort((x,y)=>x.d.localeCompare(y.d)).map(e=>{const vou=S.athletes.filter(a=>S.rsvp[e.id+a.id]==='vou');return `<div class="panel"><b>${esc(e.t)}</b> · ${fd(e.d)} ${e.h} · ${esc(e.pl)} <span class="tag">${e.kind==='macro'?'Macro '+e.cats.join(', '):'Competição'}</span>${e.card?'<span class="tag y">Card: '+CARDS[e.card].t+'</span>':''}<div class="mut">Confirmados: ${vou.length?vou.map(a=>esc(a.name)).join(', '):'ninguém ainda'}</div>${e.card&&!e.closed?`<p style="margin-top:6px"><button class="btn s" data-act="close_ev" data-id="${e.id}">Encerrar e entregar card aos confirmados</button></p>`:''}${e.closed?'<div class="tag g">Encerrado</div>':''}</div>`}).join('')}
 <h3>Novo evento macro</h3><div class="fr"><div><label>Título</label><input data-f="evT" value="${esc(V.form.evT||'')}"></div><div><label>Data</label><input type="date" data-f="evD" value="${V.form.evD||''}"></div><div><label>Hora</label><input data-f="evH" placeholder="14:00" value="${esc(V.form.evH||'')}"></div><div><label>Local</label><input data-f="evP" value="${esc(V.form.evP||'')}"></div></div><div>${CATS.map(c=>`<label class="ck" style="display:inline-flex;margin-right:10px"><input type="checkbox" data-f="evC_${c}" ${V.form['evC_'+c]?'checked':''}> ${c}</label>`).join('')}</div><div class="fr"><div><label>Card do evento (opcional)</label><select data-f="evK"><option value="">Nenhum</option>${Object.keys(CARDS).filter(k=>CARDS[k].p==='comp'||CARDS[k].p==='marc').map(k=>`<option value="${k}" ${V.form.evK===k?'selected':''}>${CARDS[k].t}</option>`).join('')}</select></div></div><button class="btn" data-act="evnew">Publicar na agenda</button>`}
ACT.evnew=()=>{const f=V.form,cats=CATS.filter(c=>f['evC_'+c]);if(!(f.evT||'').trim()||!f.evD||!cats.length){toast('Informe título, data e ao menos uma categoria');return}S.events.push({id:uid(),kind:'macro',t:f.evT.trim(),d:f.evD,h:f.evH||'09:00',pl:f.evP||'A definir',cats,card:f.evK||null,closed:false});log('SACI','Criou evento macro: '+f.evT.trim());V.form={};toast('Evento publicado: aparece na agenda dos atletas')};
ACT.close_ev=d=>{const e=S.events.find(x=>x.id===d.id);let n=0;S.athletes.forEach(a=>{if(S.rsvp[e.id+a.id]==='vou'){a.stats.eventos++;if(award(a.id,e.card))n++}});e.closed=true;log('SACI','Encerrou evento: '+e.t+' ('+n+' cards)');toast(n+' card(s) entregue(s)')};
function crit(s){const ks=Object.keys(s.obs).filter(k=>s.conf[k]);const j=ks.filter(k=>k[0]==='J').length,at=ks.filter(k=>k[0]!=='J').length;return {j,at,ok:j>=2&&at>=1}}
function sFunil(){const ids=Object.keys(S.funil);if(!ids.length)return '<h2>Funil</h2><p class="mut">Vazio.</p>';
 return `<h2>Funil de atletas de interesse</h2><div class="panel">Visível só para SACI e formação. O treinador só registra; o atleta e a família não veem o status.</div>`+ids.map(id=>{const a=A(id),f=S.funil[id],sg=S.signals.filter(s=>s.aid===id);
  return `<div class="panel"><div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px"><div><b>${esc(a.name)}</b> · ${a.cat} · ${esc(P(a.partner).name)}${a.mat==='tardia'?' <span class="tag r">Maturação tardia indicada: ler o físico com cautela</span>':a.mat==='obs'?' <span class="tag y">Maturação a observar</span>':''}</div><div><select data-chg="fstat" data-a="${id}">${FUNIL.map(s=>`<option ${f.status===s?'selected':''}>${s}</option>`).join('')}</select></div></div>
  ${sg.map(s=>{const c=crit(s);return `<div style="margin-top:8px"><div class="mut">Indicação de ${fd(s.d)} por ${esc(T(s.tr).name)} · confirmados: ${c.j} de jogo, ${c.at} de aprend./atitude <span class="tag ${c.ok?'g':''}">${c.ok?'critério mínimo atingido [Inferência]':'em formação'}</span></div>${Object.keys(s.obs).map(k=>`<div class="sig"><div class="ev2"><b>${k}</b> ${esc(SIGNALS.find(x=>x.id===k).t)}</div>${s.conf[k]?`<span class="tag g">Confirmado ${fd(s.conf[k])}</span>`:`<button class="btn s" data-act="conf" data-s="${s.id}" data-k="${k}">Confirmar no evento</button>`}</div>`).join('')}</div>`}).join('')}
  <p style="margin-top:8px"><button class="btn s o" data-act="arch" data-a="${id}">Arquivar e apagar dados individuais</button></p></div>`}).join('')}
ACT.fstat=(d,el)=>{S.funil[d.a].status=el.value;log('SACI','Funil: '+A(d.a).name+' → '+el.value);toast('Status atualizado')};
ACT.conf=d=>{const s=S.signals.find(x=>x.id===d.s);s.conf[d.k]=TODAY;log('SACI','Confirmou sinal '+d.k+' ('+A(s.aid).name+')');render()};
ACT.arch=d=>{const a=A(d.a);S.signals=S.signals.filter(s=>s.aid!==d.a);delete S.funil[d.a];S.counts.archived++;log('SACI','Arquivou e apagou dados individuais do funil ('+a.name+')');toast('Arquivado: dados individuais apagados, contagem mantida')};
function sConv(){const cs=S.reqs.filter(r=>r.kind==='conv');return `<h2>Convocatórias</h2><p class="mut">Fluxo: SACI emite → responsável é avisado → responsável libera → card aparece no álbum do atleta.</p>${cs.map(r=>`<div class="panel">${esc(A(r.aid).name)} · ${esc(r.title)} · ${fd(r.date)} <span class="tag ${r.status==='ok'?'g':'y'}">${r.status==='ok'?'Liberada':'Aguardando responsável'}</span></div>`).join('')||''}
 <div class="panel"><b>Já emitida:</b> Gabriel Souza · Rodada Colorada Sub-13 · 05/12/2026 <span class="tag g">Liberada</span></div>
 <h3>Nova convocatória</h3><div class="fr"><div><label>Atleta</label><select data-f="cvA">${S.athletes.map(a=>`<option value="${a.id}" ${V.form.cvA===a.id?'selected':''}>${esc(a.name)} (${a.cat})</option>`).join('')}</select></div><div><label>Título</label><input data-f="cvT" value="${esc(V.form.cvT||'')}" placeholder="Rodada Colorada Sub-11"></div><div><label>Data</label><input type="date" data-f="cvD" value="${V.form.cvD||''}"></div></div><button class="btn" data-act="cvnew">Emitir convocatória</button>`}
ACT.cvnew=()=>{const f=V.form,aid=f.cvA||S.athletes[0].id,a=A(aid);if(!(f.cvT||'').trim()||!f.cvD){toast('Informe título e data');return}
 const eid=uid();S.events.push({id:eid,kind:'conv',t:f.cvT.trim(),d:f.cvD,h:'09:00',pl:'Centro de treinamento',who:[aid],rel:false});S.reqs.push({id:uid(),kind:'conv',aid,eid,title:f.cvT.trim(),date:f.cvD,status:'pend'});S.notifs.push({id:uid(),aid,aud:'resp',text:'Comunicado do Inter sobre '+a.name.split(' ')[0]+': há uma convocação aguardando sua liberação (aba Aprovar).',seen:false});log('SACI','Emitiu convocação: '+f.cvT.trim()+' ('+a.name+')');V.form={};toast('Convocatória emitida: responsável avisado')};
render();
